// Package installps1 tests install.ps1 on Windows against a local release
// signed with a minisign key generated by the test (SRS FR-21.4,
// FR-21.22). The script is run by both supported invocations, `irm | iex`
// and `powershell -ExecutionPolicy Bypass -File`, under Windows PowerShell
// 5.1 and, when installed, PowerShell 7. Off Windows the tests only check
// the script's embedded key.
package installps1

import (
	"archive/zip"
	"bytes"
	"crypto/rand"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"net"
	"net/http"
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"slices"
	"strings"
	"testing"
	"time"

	"aead.dev/minisign"

	"github.com/ethan03805/secure-mcp-gateway/internal/reqtest"
)

const version = "9.9.9"

var (
	archiveName = fmt.Sprintf("smcp_%s_windows_%s.zip", version, runtime.GOARCH)
	sumsName    = fmt.Sprintf("smcp_%s_checksums.txt", version)
	binaries    = map[string]string{"smcpd.exe": "smcpd test\r\n", "smcpctl.exe": "smcpctl test\r\n", "smcp-stdio.exe": "smcp-stdio test\r\n"}
	zoneID      = []byte("[ZoneTransfer]\r\nZoneId=3\r\n")
)

func zipOf(t *testing.T, files map[string]string) []byte {
	t.Helper()
	var buf bytes.Buffer
	zw := zip.NewWriter(&buf)
	names := make([]string, 0, len(files))
	for n := range files {
		names = append(names, n)
	}
	slices.Sort(names)
	for _, n := range append(names, "README.md") {
		w, err := zw.CreateHeader(&zip.FileHeader{Name: n, Method: zip.Deflate, Modified: time.Unix(1, 0)})
		if err != nil {
			t.Fatal(err)
		}
		body := files[n]
		if n == "README.md" {
			body = "readme\n"
		}
		if _, err := w.Write([]byte(body)); err != nil {
			t.Fatal(err)
		}
	}
	if err := zw.Close(); err != nil {
		t.Fatal(err)
	}
	return buf.Bytes()
}

func sumLine(b []byte, name string) string {
	s := sha256.Sum256(b)
	return hex.EncodeToString(s[:]) + "  " + name + "\n"
}

type release map[string][]byte

func clone(r release) release {
	c := release{}
	for k, v := range r {
		c[k] = append([]byte(nil), v...)
	}
	return c
}

func signPrehashed(priv minisign.PrivateKey, msg []byte, comment string) []byte {
	r := minisign.NewReader(bytes.NewReader(msg))
	_, _ = r.Read(make([]byte, len(msg)+1))
	return r.SignWithComments(priv, comment, "signature from test key")
}

func newRelease(t *testing.T, legacy bool) (release, minisign.PrivateKey, string) {
	t.Helper()
	pub, priv, err := minisign.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	arc := zipOf(t, binaries)
	sums := []byte(sumLine(arc, archiveName) + sumLine([]byte("other"), "smcp_9.9.9_linux_amd64.tar.gz"))
	comment := "smcp " + version + " file:" + sumsName
	var sig []byte
	if legacy {
		sig = minisign.SignWithComments(priv, sums, comment, "signature from test key")
	} else {
		sig = signPrehashed(priv, sums, comment)
	}
	return release{archiveName: arc, sumsName: sums, sumsName + ".minisig": sig}, priv, pub.String()
}

// shells returns the PowerShell executables to run the script with.
func shells(t *testing.T) []string {
	t.Helper()
	if runtime.GOOS != "windows" {
		t.Skip("install.ps1 installs the Windows build")
	}
	var out []string
	for _, n := range []string{"powershell.exe", "pwsh.exe"} {
		if p, err := exec.LookPath(n); err == nil {
			out = append(out, p)
		}
	}
	if len(out) == 0 {
		t.Skip("no PowerShell")
	}
	return out
}

// basePath returns PATH without the directories that hold a signature
// verifier or cosign, so that each test chooses the verifier it means.
func basePath() []string {
	var keep []string
	for _, d := range filepath.SplitList(os.Getenv("PATH")) {
		skip := false
		for _, tool := range []string{"openssl.exe", "minisign.exe", "cosign.exe"} {
			if _, err := os.Stat(filepath.Join(d, tool)); err == nil {
				skip = true
			}
		}
		if !skip && d != "" {
			keep = append(keep, d)
		}
	}
	return keep
}

// openssl3 returns an OpenSSL 3 executable, or "".
func openssl3() string {
	cands := []string{}
	if p, err := exec.LookPath("openssl"); err == nil {
		cands = append(cands, p)
	}
	pf := os.Getenv("ProgramFiles")
	for _, sub := range []string{`Git\usr\bin\openssl.exe`, `Git\mingw64\bin\openssl.exe`, `Git\clangarm64\bin\openssl.exe`, `OpenSSL\bin\openssl.exe`} {
		cands = append(cands, filepath.Join(pf, sub))
	}
	for _, c := range cands {
		out, err := exec.Command(c, "version").Output()
		if err == nil && (bytes.HasPrefix(out, []byte("OpenSSL 3")) || bytes.HasPrefix(out, []byte("OpenSSL 4"))) {
			return c
		}
	}
	return ""
}

// toolDir returns the directory of a verifier executable, added to PATH
// for the cases that use it (OpenSSL from Git for Windows needs the DLLs
// next to it).
func toolDir(_ *testing.T, exe string) string { return filepath.Dir(exe) }

type run struct {
	shell    string
	iex      bool
	from     string // -From directory instead of the HTTP server
	tools    string // a directory added to PATH, or ""
	pubkey   string
	extraEnv []string
}

type result struct {
	out, dir, tmp string
	err           error
}

func serve(t *testing.T, rel release) string {
	t.Helper()
	script, err := os.ReadFile(filepath.Join("..", "..", "install.ps1"))
	if err != nil {
		t.Fatal(err)
	}
	ln, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	srv := &http.Server{ReadHeaderTimeout: 10 * time.Second, Handler: http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path == "/install.ps1" {
			_, _ = w.Write(script)
			return
		}
		b, ok := rel[strings.TrimPrefix(r.URL.Path, "/rel/")]
		if !ok {
			http.NotFound(w, r)
			return
		}
		_, _ = w.Write(b)
	})}
	go func() { _ = srv.Serve(ln) }()
	t.Cleanup(func() { _ = srv.Close() })
	return "http://" + ln.Addr().String()
}

func runScript(t *testing.T, rel release, r run) result {
	t.Helper()
	base := serve(t, rel)
	work := t.TempDir()
	res := result{dir: filepath.Join(work, "bin"), tmp: filepath.Join(work, "tmp")}
	local := filepath.Join(work, "localappdata")
	pf := filepath.Join(work, "programfiles") // hides Git's OpenSSL unless r.tools adds one
	for _, d := range []string{res.tmp, local, pf} {
		if err := os.Mkdir(d, 0o700); err != nil {
			t.Fatal(err)
		}
	}
	path := basePath()
	if r.tools != "" {
		path = append([]string{r.tools}, path...)
	}
	env := []string{}
	for _, kv := range os.Environ() {
		k, _, _ := strings.Cut(kv, "=")
		switch strings.ToUpper(k) {
		case "PATH", "TEMP", "TMP", "LOCALAPPDATA", "PROGRAMFILES", "SMCP_VERSION", "SMCP_INSTALL_DIR", "SMCP_BASE_URL", "SMCP_FROM", "SMCP_PUBKEY", "SMCP_NO_COSIGN":
			continue
		}
		env = append(env, kv)
	}
	env = append(env, "PATH="+strings.Join(path, string(os.PathListSeparator)), "TEMP="+res.tmp, "TMP="+res.tmp,
		"LOCALAPPDATA="+local, "ProgramFiles="+pf)
	env = append(env, r.extraEnv...)
	var cmd *exec.Cmd
	if r.iex {
		env = append(env, "SMCP_VERSION=v"+version, "SMCP_INSTALL_DIR="+res.dir, "SMCP_PUBKEY="+r.pubkey)
		if r.from != "" {
			env = append(env, "SMCP_FROM="+r.from)
		} else {
			env = append(env, "SMCP_BASE_URL="+base+"/rel/")
		}
		cmd = exec.Command(r.shell, "-NoProfile", "-NonInteractive", "-Command", "irm "+base+"/install.ps1 | iex")
	} else {
		args := []string{"-NoProfile", "-NonInteractive", "-ExecutionPolicy", "Bypass", "-File", filepath.Join("..", "..", "install.ps1"),
			"-Version", "v" + version, "-Dir", res.dir, "-PubKey", r.pubkey}
		if r.from != "" {
			args = append(args, "-From", r.from)
		} else {
			args = append(args, "-BaseUrl", base+"/rel/")
		}
		cmd = exec.Command(r.shell, args...)
	}
	cmd.Env = env
	out, err := cmd.CombinedOutput()
	res.out, res.err = string(out), err
	return res
}

func refused(t *testing.T, r result, want string) {
	t.Helper()
	if r.err == nil {
		t.Fatalf("install.ps1 succeeded:\n%s", r.out)
	}
	if !strings.Contains(r.out, want) {
		t.Fatalf("output lacks %q:\n%s", want, r.out)
	}
	if _, err := os.Stat(r.dir); err == nil {
		t.Fatalf("install directory %s was created:\n%s", r.dir, r.out)
	}
	entries, _ := os.ReadDir(r.tmp)
	for _, e := range entries {
		if strings.HasPrefix(e.Name(), "smcp-install-") {
			t.Fatalf("temporary directory %s left behind:\n%s", e.Name(), r.out)
		}
	}
}

func installed(t *testing.T, r result) {
	t.Helper()
	if r.err != nil {
		t.Fatalf("install.ps1: %v\n%s", r.err, r.out)
	}
	for name, body := range binaries {
		p := filepath.Join(r.dir, name)
		b, err := os.ReadFile(p)
		if err != nil || string(b) != body {
			t.Fatalf("%s not installed: %v\n%s", name, err, r.out)
		}
		// FR-21.22: no Mark of the Web on the installed, verified files.
		if _, err := os.Stat(p + ":Zone.Identifier"); err == nil {
			t.Fatalf("%s keeps its Zone.Identifier stream", name)
		}
	}
	if !strings.Contains(r.out, "no Authenticode signature") {
		t.Fatalf("no unsigned-binary notice:\n%s", r.out)
	}
	entries, _ := os.ReadDir(r.tmp)
	for _, e := range entries {
		if strings.HasPrefix(e.Name(), "smcp-install-") {
			t.Fatalf("temporary directory %s left behind", e.Name())
		}
	}
}

// TestInstallPS1 runs every FR-21.4 case by both invocations with each
// verifier the host offers (minisign.exe, OpenSSL 3).
func TestInstallPS1(t *testing.T) {
	sh := shells(t)
	type verifier struct{ name, tools string }
	var vs []verifier
	if p, err := exec.LookPath("minisign"); err == nil {
		vs = append(vs, verifier{"minisign", toolDir(t, p)})
	}
	if o := openssl3(); o != "" {
		vs = append(vs, verifier{"openssl", toolDir(t, o)})
	}
	if len(vs) == 2 && slices.ContainsFunc(sh, func(s string) bool { return strings.EqualFold(filepath.Base(s), "powershell.exe") }) {
		// Both invocations, both verifiers, every refusal of the statement.
		reqtest.Verifies(t, "FR-21.4")
	} else {
		reqtest.Partial(t, "FR-21.4")
	}
	if len(vs) == 0 {
		t.Skip("neither minisign nor OpenSSL 3 is installed")
	}
	for _, shell := range sh {
		for _, iex := range []bool{false, true} {
			for _, v := range vs {
				name := fmt.Sprintf("%s/iex=%v/%s", strings.TrimSuffix(filepath.Base(shell), ".exe"), iex, v.name)
				t.Run(name, func(t *testing.T) {
					for _, legacy := range []bool{false, true} {
						rel, priv, pk := newRelease(t, legacy)
						r := runScript(t, rel, run{shell: shell, iex: iex, tools: v.tools, pubkey: pk})
						installed(t, r)
						if !strings.Contains(r.out, "signature verified") || !strings.Contains(r.out, "cosign is not installed") {
							t.Fatalf("legacy=%v:\n%s", legacy, r.out)
						}

						bad := clone(rel)
						bad[archiveName] = append(bad[archiveName], 0)
						refused(t, runScript(t, bad, run{shell: shell, iex: iex, tools: v.tools, pubkey: pk}), "checksum mismatch")

						bad2 := clone(bad)
						bad2[sumsName] = []byte(sumLine(bad[archiveName], archiveName))
						refused(t, runScript(t, bad2, run{shell: shell, iex: iex, tools: v.tools, pubkey: pk}), "does not verify")

						// A trusted comment changed after signing.
						bad3 := clone(rel)
						bad3[sumsName+".minisig"] = bytes.Replace(rel[sumsName+".minisig"], []byte("trusted comment: smcp"), []byte("trusted comment: smcq"), 1)
						refused(t, runScript(t, bad3, run{shell: shell, iex: iex, tools: v.tools, pubkey: pk}), "does not verify")

						// A valid signature whose trusted comment names another file.
						replay := clone(rel)
						replay[sumsName+".minisig"] = signPrehashed(priv, rel[sumsName], "file:smcp_1.0.0_checksums.txt")
						refused(t, runScript(t, replay, run{shell: shell, iex: iex, tools: v.tools, pubkey: pk}), "does not name")

						otherPub, _, _ := minisign.GenerateKey(rand.Reader)
						refused(t, runScript(t, rel, run{shell: shell, iex: iex, tools: v.tools, pubkey: otherPub.String()}), "does not verify")

						nosig := clone(rel)
						delete(nosig, sumsName+".minisig")
						refused(t, runScript(t, nosig, run{shell: shell, iex: iex, tools: v.tools, pubkey: pk}), "download failed")
					}
				})
			}
			t.Run(fmt.Sprintf("%s/iex=%v/no-verifier", strings.TrimSuffix(filepath.Base(shell), ".exe"), iex), func(t *testing.T) {
				rel, _, pk := newRelease(t, false)
				refused(t, runScript(t, rel, run{shell: shell, iex: iex, pubkey: pk}), "cannot verify the release signature")
			})
		}
	}
}

// TestInstallPS1MarkOfTheWeb: release files downloaded by a browser carry
// a Zone.Identifier stream. After the checks pass, the installed binaries
// carry none; a refused install leaves the downloaded files as they were
// (FR-21.22). Partial: the release notes and docs/install.md statements
// are checked by TestUnsignedNoticesPublished, not by a Windows run.
func TestInstallPS1MarkOfTheWeb(t *testing.T) {
	sh := shells(t)
	reqtest.Partial(t, "FR-21.22")
	o := openssl3()
	if o == "" {
		t.Skip("OpenSSL 3 is not installed")
	}
	tools := toolDir(t, o)
	for _, shell := range sh {
		for _, iex := range []bool{false, true} {
			rel, _, pk := newRelease(t, false)
			from := t.TempDir()
			for name, b := range rel {
				p := filepath.Join(from, name)
				if err := os.WriteFile(p, b, 0o644); err != nil {
					t.Fatal(err)
				}
				if err := os.WriteFile(p+":Zone.Identifier", zoneID, 0o644); err != nil {
					t.Skipf("no alternate data streams here: %v", err)
				}
			}
			installed(t, runScript(t, rel, run{shell: shell, iex: iex, from: from, tools: tools, pubkey: pk}))

			bad := t.TempDir()
			for name, b := range rel {
				if name == archiveName {
					b = append(append([]byte(nil), b...), 0)
				}
				p := filepath.Join(bad, name)
				if err := os.WriteFile(p, b, 0o644); err != nil {
					t.Fatal(err)
				}
				if err := os.WriteFile(p+":Zone.Identifier", zoneID, 0o644); err != nil {
					t.Fatal(err)
				}
			}
			refused(t, runScript(t, rel, run{shell: shell, iex: iex, from: bad, tools: tools, pubkey: pk}), "checksum mismatch")
			for name := range rel {
				if b, err := os.ReadFile(filepath.Join(bad, name) + ":Zone.Identifier"); err != nil || !bytes.Equal(b, zoneID) {
					t.Fatalf("%s lost its Zone.Identifier after a refused install: %v", name, err)
				}
			}
		}
	}
}

// TestInstallPS1EmbedsPublishedKey: install.ps1 embeds the release key that
// install.sh and SECURITY.md publish.
func TestInstallPS1EmbedsPublishedKey(t *testing.T) {
	script, err := os.ReadFile(filepath.Join("..", "..", "install.ps1"))
	if err != nil {
		t.Fatal(err)
	}
	var key string
	for _, l := range strings.Split(string(script), "\n") {
		if k, ok := strings.CutPrefix(strings.TrimSpace(l), "$ReleaseKey = '"); ok {
			key = strings.TrimSuffix(k, "'")
		}
	}
	var pub minisign.PublicKey
	if err := pub.UnmarshalText([]byte(key)); err != nil {
		t.Fatalf("install.ps1 $ReleaseKey %q: %v", key, err)
	}
	for _, f := range []string{"SECURITY.md", "install.sh", "docs/install.md"} {
		b, err := os.ReadFile(filepath.Join("..", "..", f))
		if err != nil {
			t.Fatal(err)
		}
		if !strings.Contains(string(b), key) {
			t.Errorf("%s does not publish the key %s that install.ps1 embeds", f, key)
		}
	}
}

// TestUnsignedNoticesPublished: the release notes template, docs/install.md
// and install.ps1 state that the Windows binaries are unsigned, what
// SmartScreen and Smart App Control do, and how to verify them (FR-21.22).
func TestUnsignedNoticesPublished(t *testing.T) {
	reqtest.Partial(t, "FR-21.22")
	for _, f := range []string{".goreleaser.yaml", "docs/install.md", "install.ps1"} {
		b, err := os.ReadFile(filepath.Join("..", "..", f))
		if err != nil {
			t.Fatal(err)
		}
		s := string(b)
		for _, want := range []string{"Authenticode", "SmartScreen", "Smart App Control", "minisign", "SHA-256"} {
			if !strings.Contains(s, want) {
				t.Errorf("%s does not mention %s", f, want)
			}
		}
	}
}
